import com.holdmyspot.codexunleashed.scheduler.LinuxProcessTree;
import com.holdmyspot.codexunleashed.scheduler.LinuxResidency;
import com.holdmyspot.codexunleashed.scheduler.LinuxSupervisor;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.Properties;

public final class ResidencyFixture {
    public static void main(String[] args) throws Exception {
        Path work = Path.of(args[0]);
        Path parent = Path.of(args[1]);
        Path ownerJar = Path.of(args[2]);
        int uid = Integer.parseInt(args[3]);
        int gid = Integer.parseInt(args[4]);
        String module = LinuxResidency.class.getModule().getName();
        Path origin = Path.of(LinuxResidency.class.getProtectionDomain().getCodeSource().getLocation().toURI());
        if ("com.holdmyspot.codexunleashed.tooling".equals(module) == false)
            throw new AssertionError("Sampler is not loaded from the named tooling module");
        if (origin.equals(ownerJar) == false)
            throw new AssertionError("Sampler is not loaded from the expected tested JAR");
        var launch = new LinuxProcessTree.Launch(parent, work,
            Path.of(System.getProperty("java.home"), "bin", "java"), ownerJar,
            List.of("/usr/bin/python3", work.resolve("workload.py").toString(), work.toString()),
            Map.of(), work, uid, gid);
        Properties receipt = new Properties();
        receipt.setProperty("module", module);
        receipt.setProperty("origin", origin.toString());
        Path outer;
        try (LinuxSupervisor owner = LinuxSupervisor.prepare(launch, Duration.ofSeconds(15))) {
            outer = owner.directory();
            receipt.setProperty("outer", outer.toString());
            receipt.setProperty("supervisor.pid", Long.toString(owner.pid()));
            receipt.setProperty("root.pid", Long.toString(owner.rootPid()));
            owner.release();
            long deadline = System.nanoTime() + Duration.ofSeconds(15).toNanos();
            Path ready = work.resolve("workload-ready.properties");
            while (Files.exists(ready) == false) {
                if (System.nanoTime() >= deadline)
                    throw new AssertionError("Workload did not publish touched-memory readiness");
                Thread.sleep(10);
            }
            Properties workload = new Properties();
            try (var input = Files.newBufferedReader(ready)) {
                workload.load(input);
            }
            long root = Long.parseLong(workload.getProperty("root"));
            long leaf = Long.parseLong(workload.getProperty("leaf"));
            if (root != owner.rootPid())
                throw new AssertionError("Readiness identifies a different workload root");
            for (long pid : List.of(owner.pid(), root, leaf)) {
                Path source = Path.of("/proc", Long.toString(pid), "cgroup");
                String record = Files.readString(source);
                receipt.setProperty("membership." + pid, record);
                if (record.startsWith("0::/") == false)
                    throw new AssertionError("Runner is not unified-v2-only: " + record);
                String relative = record.substring("0::/".length(), record.length() - 1);
                Path actual = Path.of("/sys/fs/cgroup").resolve(relative).toRealPath();
                if (actual.startsWith(outer) == false)
                    throw new AssertionError("Actual process membership lies outside owned subtree: " + actual);
                if (Files.readAllLines(actual.resolve("cgroup.procs")).contains(Long.toString(pid)) == false)
                    throw new AssertionError("Mounted membership does not contain expected process " + pid);
            }
            LinuxResidency.Sample sample = LinuxResidency.read(Path.of("/sys/fs/cgroup"), Path.of("/proc"), outer);
            if (sample.processes() != 3)
                throw new AssertionError("Expected the supervisor, root and leaf; observed " + sample);
            if (sample.residentBytes() < 48L * 1024 * 1024)
                throw new AssertionError("Held touched-memory workload not represented: " + sample);
            receipt.setProperty("sample.resident.bytes", Long.toString(sample.residentBytes()));
            receipt.setProperty("sample.processes", Integer.toString(sample.processes()));
            receipt.setProperty("leaf.pid", Long.toString(leaf));
            receipt.setProperty("root-alive-at-sample", Boolean.toString(ProcessHandle.of(root).orElseThrow().isAlive()));
            receipt.setProperty("leaf-alive-at-sample", Boolean.toString(ProcessHandle.of(leaf).orElseThrow().isAlive()));
        }
        if (Files.exists(outer))
            throw new AssertionError("Owner close left its outer cgroup");
        var empty = LinuxResidency.read(Path.of("/sys/fs/cgroup"), Path.of("/proc"), parent);
        if (empty.equals(new LinuxResidency.Sample(0, 0)) == false)
            throw new AssertionError("Owned parent retained process memory after owner close: " + empty);
        receipt.setProperty("owner.group.removed", "true");
        receipt.setProperty("empty.parent.bytes", Long.toString(empty.residentBytes()));
        receipt.setProperty("empty.parent.processes", Integer.toString(empty.processes()));
        receipt.setProperty("status", "passed");
        try (var output = Files.newOutputStream(work.resolve("residency.xml"))) {
            receipt.storeToXML(output, "Native owned-process residency proof");
        }
        System.out.println("native_residency=passed; processes=3; post_close_processes=0");
    }
}
